	if (nTop >= 2)
		nNpcIdx = (int)Lua_ValueToNumber(L, 2);
	else
	{
		int nPlayerIdx = GetPlayerIndex(L);
		if (nPlayerIdx <= 0) { Lua_PushNumber(L, 0); return 1; }
