int LuaJX2_RemoteExecute(Lua_State* L)
{
	if (Lua_GetTopIndex(L) < 3 || !Lua_IsString(L, 1) || !Lua_IsString(L, 2) || !Lua_IsNumber(L, 3))
		return 0;
	const char* szScript = Lua_ValueToString(L, 1);
	const char* szFunc = Lua_ValueToString(L, 2);
	int nHandle = (int)Lua_ValueToNumber(L, 3);
	if (!szScript[0] || !szFunc[0] || nHandle < 0)
		return 0;
	const char* szCb = (Lua_GetTopIndex(L) >= 4 && Lua_IsString(L, 4)) ? Lua_ValueToString(L, 4) : NULL;
	int nCbId = (Lua_GetTopIndex(L) >= 5 && Lua_IsNumber(L, 5)) ? (int)Lua_ValueToNumber(L, 5) : 0;
	// duong dan: ha thuong + remap \script\lib -> scriptjx2\lib (cung luat sJX2RemapScriptPath cua Include)
	char szLow[MAX_PATH]; g_StrCpyLen(szLow, (char*)szScript, MAX_PATH); g_StrLower(szLow);
	KLuaScript* pScript = (KLuaScript*)g_GetScript(szLow);
	if (!pScript)
	{
		char szAlt[MAX_PATH]; strcpy(szAlt, szLow);
		char* p = strstr(szAlt, "\\script\\lib\\");
		if (p) { memmove(p + 15, p + 12, strlen(p + 12) + 1); memcpy(p, "\\scriptjx2\\lib\\", 15); pScript = (KLuaScript*)g_GetScript(szAlt); }
	}
	if (!pScript) { g_DebugLog((LPSTR)"[BAIREN] RemoteExecute: script chua nap %.128s", szLow); return 0; }
	// hRes = OB_Create() - dung cung API voi LuaOB_Create (xem ScriptFuns.cpp); gia su co ham C g_ObjBufferCreate()
	int hRes = sObjBufferCreateForScript();	// bo boc quanh LuaOB_Create: goi LuaOB_Create tren mot state tam hoac tach phan C cua no ra ham dung chung
	char szCall[512];
	sprintf(szCall, "%s(%d,%d,0)", szFunc, nHandle, hRes);	// ReceiveExc(ParamHandle, ResultHandle, dwGSID=0)
	int nTop = 0; pScript->SafeCallBegin(&nTop);
	if (lua_dostring(pScript->m_LuaState, szCall) != 0) g_DebugLog((LPSTR)"[BAIREN] RemoteExecute LOI %.200s", szCall);
	pScript->SafeCallEnd(nTop);
	if (szCb && szCb[0])
	{
		sprintf(szCall, "%s(%d,%d)", szCb, nCbId, hRes);	// RemoteExc_CallBack(Param, ResultHandle) trong state DANG GOI
		int nTop0 = Lua_GetTopIndex(L);
		if (lua_dostring(L, szCall) != 0) g_DebugLog((LPSTR)"[BAIREN] RemoteExecute cb LOI %.200s", szCall);
		lua_settop(L, nTop0);
	}
	sObjBufferRelease(hRes);
	return 0;
}
