int LuaCallPlayerFunction(Lua_State* L)
{
	int nParamNum = Lua_GetTopIndex(L);
	if (nParamNum < 2) return 0;
	int nPlayerIdx = (int)Lua_ValueToNumber(L, 1);
	if (nPlayerIdx <= 0 || nPlayerIdx >= MAX_PLAYER) return 0;
	lua_getglobal(L, SCRIPT_PLAYERINDEX);
	int nOldTop = lua_gettop(L);		// PlayerIndex cu nam o day
	Lua_PushNumber(L, nPlayerIdx);
	lua_setglobal(L, SCRIPT_PLAYERINDEX);
	int nBase = lua_gettop(L);		// = nOldTop
	lua_pushvalue(L, 2);
	int nArgs = 0;
	for (int i = 3; i <= nParamNum; i++) { lua_pushvalue(L, i); nArgs++; }
	lua_rawcall(L, nArgs, LUA_MULTRET);	// [BAIREN 22/08] tra ket qua nhu Linux
	int nRes = lua_gettop(L) - nBase;
	lua_pushvalue(L, nOldTop);
	lua_setglobal(L, SCRIPT_PLAYERINDEX);
	return nRes;	// ket qua nam tren dinh stack (nRes gia tri)
}

